# Robinson projection constants, fitted to the paths below. project_lonlat()
# must stay in lockstep with them: it is what places project pins by real
# coordinates, and any drift would float pins off their countries.
_ROB_X = [1.0, 0.9986, 0.9954, 0.99, 0.9822, 0.973, 0.96, 0.9427, 0.9216, 0.8962, 0.8679, 0.835, 0.7986, 0.7597, 0.7186, 0.6732, 0.6213, 0.5722, 0.5322]
_ROB_Y = [0.0, 0.062, 0.124, 0.186, 0.248, 0.31, 0.372, 0.434, 0.4958, 0.5571, 0.6176, 0.6769, 0.7346, 0.7903, 0.8435, 0.8936, 0.9394, 0.9761, 1.0]
_MIN_X = -2.635168375836761
_MAX_Y = 1.30653175025466
_SCALE = 189.74119626842895


def project_lonlat(lon, lat):
    """Longitude/latitude in degrees -> (x, y) in this module's viewBox."""
    lat = max(-90.0, min(90.0, lat))
    a = abs(lat)
    i = min(int(a / 5.0), 17)
    frac = (a - i * 5.0) / 5.0
    rx = _ROB_X[i] + (_ROB_X[i + 1] - _ROB_X[i]) * frac
    ry = _ROB_Y[i] + (_ROB_Y[i + 1] - _ROB_Y[i]) * frac
    x = 0.8487 * rx * math.radians(lon)
    y = 1.3523 * ry
    if lat < 0:
        y = -y
    return ((x - _MIN_X) * _SCALE, (_MAX_Y - y) * _SCALE)


